-- CATCH 块中声明多个变量并赋值
DECLARE @remark1 VARCHAR(2000),
        @rem_20 VARCHAR(5000),
        @recipient VARCHAR(2000),
        @re_org VARCHAR(20),
        @body VARCHAR(MAX),
        @send_id VARCHAR(50) = NEWID();

SELECT @remark1 = '自动点模出错';
SELECT @body = '自动点模出错';
SELECT @rem_20 = ERROR_MESSAGE();  -- 获取错误消息

-- 声明单个变量
DECLARE @var_name data_type [= default_value];

-- 声明多个变量（逗号分隔）
DECLARE @v1 INT, @v2 VARCHAR(100), @v3 DATETIME;

-- 声明时赋默认值（SQL Server 2008+）
DECLARE @count INT = 0, @name VARCHAR(50) = 'test';

-- 声明表变量
DECLARE @temp_table TABLE (
    id INT PRIMARY KEY,
    name VARCHAR(100)
);

BEGIN TRY
    BEGIN TRANSACTION;
    -- ... 核心业务逻辑 ...
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    -- Step 1: 回滚事务
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    -- ... 后续错误处理 ...
END CATCH;

-- 显式事务
BEGIN TRANSACTION [tran_name];
    -- DML 语句
COMMIT TRANSACTION [tran_name];   -- 提交
-- 或
ROLLBACK TRANSACTION [tran_name];  -- 回滚

-- 保存点（嵌套事务中部分回滚）
BEGIN TRANSACTION;
    SAVE TRANSACTION save_point1;
    -- 某些操作
    ROLLBACK TRANSACTION save_point1;  -- 只回滚到保存点，不回滚整个事务
COMMIT TRANSACTION;

BEGIN CATCH
    -- ================================================================
    -- Step 1: 回滚事务
    -- ================================================================
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION

    -- ================================================================
    -- Step 2: 关闭并释放游标（如果仍处于打开状态）
    -- ================================================================
    IF CURSOR_STATUS('global', 'auto_mod_cur') <> -3
       OR CURSOR_STATUS('local', 'auto_mod_cur') <> -3
    BEGIN
        CLOSE auto_mod_cur;
        DEALLOCATE auto_mod_cur;
    END;

    -- ================================================================
    -- Step 3: 调用系统错误日志记录存储过程
    -- ================================================================
    EXEC dbo.p_sys_raiserror;

    -- ================================================================
    -- Step 4: 声明变量并获取错误信息
    -- ================================================================
    DECLARE @remark1 VARCHAR(2000),
            @rem_20 VARCHAR(5000),
            @recipient VARCHAR(2000),
            @re_org VARCHAR(20),
            @body VARCHAR(MAX),
            @send_id VARCHAR(50) = NEWID();

    SELECT @remark1 = '自动点模出错';
    SELECT @body = '自动点模出错';
    SELECT @rem_20 = ERROR_MESSAGE();  -- 获取错误消息

    -- ================================================================
    -- Step 5: 查询通知接收人列表（使用 STRING_AGG 聚合）
    -- ================================================================
    SELECT @recipient = STRING_AGG(b.emp_no, ',')
    FROM tb_mes_msg_type a
        LEFT JOIN tb_mes_msg_type_users b
            ON a.msg_type_code = b.msg_type_code
    WHERE a.msg_type_code = 'MJTBCC'

    -- ================================================================
    -- Step 6: 发送多渠道通知（微信/PC/Android 推送）
    -- ================================================================
    EXEC zgRdp.dbo.p_sys_call_make_msg
        @MsgTile = @remark1,
        @MsgType = 0,
        @Body = @rem_20,        -- 使用 ERROR_MESSAGE() 的结果
        @SheetNo = '',
        @LevelId = 0,
        @WeixinPush = 1,
        @PcPush = 1,
        @AndroidPush = 1,
        @SendUser = '',
        @RecUsers = @recipient,
        @RecRole = '',
        @RecSql = '',
        @MenuId = '',
        @temp_id = 'DxOjZaab_bWL6mwzjVLq5bWXnFycR35MH2DwQAgJimQ',
        @define1 = '',
        @define2 = '',
        @define3 = '',
        @define4 = '',
        @define5 = '',
        @extend_field = '';
END CATCH;

