-- 声明游标
DECLARE auto_mod_cur CURSOR FOR
SELECT line_no, eqm_no, model_no, mold_count, mold_limit
FROM #jt_moldinfo
WHERE rn = 1
  AND need_mold = 1;

-- 打开游标
OPEN auto_mod_cur;

-- 获取第一行
FETCH NEXT FROM auto_mod_cur INTO
    @line_no, @eqm_no, @model_no, @mold_count, @mold_limit;

-- 循环处理
WHILE @@FETCH_STATUS = 0
BEGIN
    -- 业务逻辑：检查型号数是否超过下限
    IF @mold_count > @mold_limit
    BEGIN
        DECLARE @msg VARCHAR(1000);
        SET @msg = FORMATMESSAGE(
            '自动点模失败。机台当前有任务型号数%s大于下限%s，本次不点模。',
            CAST(@mold_count AS VARCHAR(20)),
            CAST(@mold_limit AS VARCHAR(20))
        );
        RAISERROR(@msg, 16, 1);
    END

    -- 获取下一行（必须放在循环体最后）
    FETCH NEXT FROM auto_mod_cur INTO
        @line_no, @eqm_no, @model_no, @mold_count, @mold_limit;
END

-- 关闭并释放游标
CLOSE auto_mod_cur;
DEALLOCATE auto_mod_cur;

-- 1. EXISTS：判断是否存在（推荐，性能好）
SELECT * FROM orders o
WHERE EXISTS (
    SELECT 1 FROM items i
    WHERE i.order_id = o.id AND i.price > 100
);

-- 2. NOT EXISTS：判断不存在
SELECT * FROM customers c
WHERE NOT EXISTS (
    SELECT 1 FROM orders o
    WHERE o.cust_id = c.id
);

-- 3. IN：值在列表中
SELECT * FROM orders
WHERE status IN ('A', 'B', 'C');

-- 4. IN 子查询
SELECT * FROM orders
WHERE cust_id IN (SELECT id FROM customers WHERE vip = 1);

-- 5. NOT IN 子查询
SELECT * FROM orders
WHERE cust_id NOT IN (SELECT id FROM blacklist);

-- 6. 标量子查询
SELECT o.*, (SELECT COUNT(*) FROM items i WHERE i.order_id = o.id) AS item_count
FROM orders o;

-- 7. 派生表（FROM 子句中的子查询）
SELECT t.* FROM (
    SELECT cat, COUNT(*) AS cnt FROM products GROUP BY cat
) t WHERE t.cnt > 10;

-- 8. ANY / ALL / SOME
SELECT * FROM products
WHERE price > ALL (SELECT price FROM products WHERE cat = 'A');

-- SQL Server 2017+：STRING_AGG
SELECT STRING_AGG(emp_no, ',') FROM users;

-- SQL Server 2016 及以下：FOR XML PATH
SELECT STUFF((
    SELECT ',' + emp_no
    FROM users
    FOR XML PATH(''), TYPE
).value('.', 'VARCHAR(MAX)'), 1, 1, '');

-- 去重后聚合
SELECT STRING_AGG(emp_no, ',')
FROM (SELECT DISTINCT emp_no FROM users) t;

-- 场景：查找 status 不等于 'A' 的行
SELECT * FROM orders WHERE status <> 'A';
-- 如果某行 status 为 NULL，该行不会被返回！
-- 因为 NULL <> 'A' 的结果是 UNKNOWN，被 WHERE 过滤

-- 正确写法：显式包含 NULL
SELECT * FROM orders WHERE status <> 'A' OR status IS NULL;
-- 或
SELECT * FROM orders WHERE ISNULL(status, '') <> 'A';

